import releaseNotesGenerator from "@semantic-release/release-notes-generator";

const pluginConfig = {
  preset: "conventionalcommits",
  presetConfig: {
    types: [
      { type: "feat", section: "Features" },
      { type: "fix", section: "Bug Fixes" },
    ],
  },
};

const context = {
  cwd: process.cwd(),
  options: { repositoryUrl: "https://github.com/zentered-studios/mcpsignals" },
  lastRelease: { version: "2.3.1", gitTag: "v2.3.1", gitHead: "HEAD~1" },
  nextRelease: { version: "2.3.2", gitTag: "v2.3.2", type: "patch" },
  commits: [
    {
      hash: "abc1234",
      message: "fix: pin typescript to ^5.9 pending rollup-plugin-dts TS7 support",
      committerDate: new Date().toISOString(),
    },
  ],
  logger: { log: () => {}, error: () => {} },
};

const notes = await releaseNotesGenerator.generateNotes(pluginConfig, context);
console.log("SUCCESS");
console.log(notes);

